import Testing
import Foundation
@testable import EufyKit

private func big(_ hex: String) -> BigUInt { BigUInt(bytes: Data(hex: hex)!) }

@Test func bigUIntArithmeticMatchesReference() {
    let x = big("08ede0d7c3baea9e13deef86ab1031d0f646e1f40a097c976bf46c697d2caf82eeeacbe226e875555790f82ec1d3fcff2a3af4d46b0a18e8830e07bc1e398f1012bd4acefaecbd389be4bcfc49b64a0872e6cc3ababced20"), y = big("795e82451abd81f1d69ed617f5e837d70820fe119a72d174c9df6acc011cdd9474031b7f26144b98289fcd59a54a7bb1fee08f571242425051c1ccd17f9acae01f5057ca02135e92b1d3f2")
    #expect((x * y).bytes(length: 163) == [UInt8](Data(hex: "")!))
    #expect((x % y).bytes(length: 80) == [UInt8](Data(hex: "000000000051b4a201c90ed5f0fd22d965c1a73fa718902221bcd697821bafdc3ab66ad7be0bb89288d240f1fb12f6b38604926e98cc36d0672f2980d2868ef9c0149f17432c834d1c416d6e06475056")!))
    #expect(((x + y) - y) == x)
}

@Test func bigUIntModPow1024MatchesReference() {
    let r = big("a170b33839263059f28c105d1fb17c2390c192cfd3ac94af0f21ddb66cad4a268d116ece1738f7d93d9c172411e20b8f6b0d549b6f03675a1600a35a099950d836f675cc81e74ef5e8e25d940ed904759531985d5d9dc9f81818e811892f902bd23f0824128b2f330c5c7fd0a6a3a4506513270e269e0d37f2a74de452e6b438").power(big("18f135d25f557203301850c5a38fd547923a736994e3bf911a61dbe22e44158bae97ba94d0eda82f8f6d05584ef8aa38922766581e27a1c08a6a63ec24ede6a46b4cb2424a23d5962217beaddbc496cb8e81973e0becd7b03898d190f9ebdacc0cb1e29c658cda1495e60af593bd04cf0fd630f1f29d0da9953f48f1a09f76b5"), modulus: big("d7ee05cde00902c77ebff206867347214cdd2055930d6eaf14f4733f3e7d1bfbc7a2ea20b2f14c942e05319acb5c74273f98e2774cbd87ad5c90a9587403e430ec66a78795e761d17731af10506bf2efc6f877186d76b07e881ed162ae2eb1547f15052434b9b5df9e7769b10f4205b4907a70c31012f037b64ce4228c38fb29"))
    #expect(r.bytes(length: 128) == [UInt8](Data(hex: "220f6a63f20e02dab8e9bb5ae47d2477048a52b2e8d951eff23681f891633c41f1f5ce8f5475dbcee65607db9e729b2389afc969d2041913a2cf69e3177baa57e7d11e0d91cff845358e9c59378de21c87592cb963f99beaa353dc35d7d918f968219f43de43a1c0c6c15c5bf2e4a6f6bd1a1375b9703b102bb2a0531bde7b6f")!))
}
